// non-static data member, for any aggregate type.
template <typename T>
constexpr bool structural_equals(const T& a, const T& b) {
    bool equal = true;
    template for (constexpr std::meta::info member :
                  std::meta::nonstatic_data_members_of(^^T)) {
        if (a.[:member:] != b.[:member:]) {
            equal = false;
        }
    }
