template<typename... Rest>
void process(Rest&&...);

void f() {
    auto [...rest] = get_empty();
    if constexpr (sizeof...(rest) == 0) {
        std::cout << "note: rest is empty, nothing to process\n";
    } else {
        (process(rest), ...);
    }
}
```

